DROP VIEW IF EXISTS mv_yearly_plant_yield;
CREATE MATERIALIZED VIEW mv_yearly_plant_yield AS
SELECT 
    p.sitelabel,
    DATE_TRUNC('year', pr.snapts)::date AS year,
    SUM(CAST(ep.elec_perf_snapshot->'energy_yield'->>'energy_yield_kwh' AS numeric))::real AS total_yield_kwh
FROM plants p
JOIN plant_record pr ON p.sitekey = pr.sitetie
JOIN electrical_performance ep ON pr.snapkey = ep.snaplink
GROUP BY p.sitelabel, DATE_TRUNC('year', pr.snapts)::date;
REFRESH MATERIALIZED VIEW mv_yearly_plant_yield;
SELECT sitelabel, total_yield_kwh FROM mv_yearly_plant_yield WHERE EXTRACT(YEAR FROM year) = 2023 ORDER BY total_yield_kwh DESC;

